import sys
from itertools import combinations

def landau_criterion(d):
    n = len(d)
    for k in range(n - 1):
        if sum(d[:k + 1]) > k * (k + 1) // 2 + sum(d[k + 1:n]):
            return False
    return sum(d) == n * (n - 1) // 2

def construct_tournament(scores):
    n = len(scores)
    matrix = [[0] * n for _ in range(n)]
    used = [False] * n
    for i in range(n):
        for j in range(n):
            if i != j and not used[j] and scores[i] > 0:
                matrix[i][j] = 1
                scores[i] -= 1
                used[j] = True
    return matrix

def find_min_tournament(S):
    S = sorted(S)
    for n in range(len(S), 32):
        for comb in combinations(range(n), len(S)):
            scores = [0] * n
            for i, s in enumerate(S):
                scores[comb[i]] = s
            if landau_criterion(scores):
                matrix = construct_tournament(scores[:])
                return n, matrix
    return None

def main():
    import sys
    input = sys.stdin.read().split()
    m = int(input[0])
    S = list(map(int, input[1:]))
    result = find_min_tournament(S)
    if result is None:
        print('=(')
    else:
        n, matrix = result
        print(n)
        for row in matrix:
            print(''.join(map(str, row)))

main()
